  // mouse drag (touch already swipes natively)
  let dx=null,sl0=0;track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')return;dx=e.clientX;sl0=track.scrollLeft;track.classList.add('dragging');track.setPointerCapture(e.pointerId)});track.addEventListener('pointermove',e=>{if(dx!==null)track.scrollLeft=sl0-(e.clientX-dx)});track.addEventListener('pointerup',e=>{if(dx===null)return;const d=e.clientX-dx;dx=null;track.classList.remove('dragging');go(idx+(d<-40?1:d>40?-1:0))});
