document.querySelectorAll('.ig-post').forEach(buildPost);

// Deck shuffle shared by the card-02 and card-03 stacks: throw the old front card, cascade the rest forward, pop the new one in.
const deckBase=d=>`translateX(calc(-50% - 16px + ${d*16}px)) translateY(${d*-5}px) rotate(${d*3.5}deg) scale(${1-d*.05})`;
function deckThrow(card,dir=1,from=deckBase(0)){if(reduce())return;card.animate([{transform:from,opacity:1,filter:'blur(0px) brightness(1)'},{transform:`translateX(calc(-50% - 16px + ${dir*-42}%)) translateY(-14px) rotate(${dir*-9}deg) scale(.97)`,opacity:1,filter:'blur(0px) brightness(1)',offset:.35},{transform:`translateX(calc(-50% - 16px + ${dir*-125}%)) translateY(10px) rotate(${dir*-22}deg) scale(.9)`,opacity:0,filter:'blur(6px) brightness(.7)'}],{duration:560,easing:'cubic-bezier(.45,0,.2,1)'})}
