  function setFront(k,dir){const prev=posts[front],moved=k!==front;if(moved&&prev)deckThrow(prev,dir??1);front=k;posts.forEach((p,i)=>{const d=(i-front+posts.length)%posts.length;p.style.setProperty('--d',d);p.style.zIndex=10-d;p.classList.toggle('front',d===0);p.inert=d!==0;p.setAttribute('aria-hidden',String(d!==0))});tabs.forEach((t,i)=>{t.setAttribute('aria-selected',String(i===front));t.tabIndex=i===front?0:-1});if(moved)deckSettle(posts,front);posts.forEach(p=>p.refresh&&p.refresh())}
